def etats_existants(apps, schema_editor):
    """Données d'avant le 12/10/2026 : l'état n'était pas connu.
    - Exemplaires : « Bon état » (en stock ou prêtés), « À réparer » / « Hors service » d'après leur ancien statut.
    - Stock suivi par quantité : « Neuf » pour un consommable, « Bon état » pour le matériel prêté.
    - Sorties déjà confirmées : même règle pour l'état à la sortie.
    - Emplacements dédiés « Atelier – À réparer » et « Rebut » dans chaque magasin permanent."""
    Exemplaire = apps.get_model("stock", "Exemplaire")
    Article = apps.get_model("stock", "Article")
    StockEtat = apps.get_model("stock", "StockEtat")
    LigneSortie = apps.get_model("stock", "LigneSortie")
    Magasin = apps.get_model("stock", "Magasin")
    Emplacement = apps.get_model("stock", "Emplacement")
    Exemplaire.objects.filter(statut__in=["EN_STOCK", "PRETE"]).update(etat="BON")
    Exemplaire.objects.filter(statut="REPARATION").update(etat="A_REPARER")
    Exemplaire.objects.filter(statut="HORS_SERVICE").update(etat="HORS_SERVICE")
    avec_serie = set(Exemplaire.objects.values_list("article_id", flat=True))
    for a in Article.objects.filter(qte_stock__gt=0).exclude(id__in=avec_serie):
        StockEtat.objects.update_or_create(article=a, etat="NEUF" if a.type == "CONSOMMABLE" else "BON",
                                           defaults={"quantite": a.qte_stock})
    for ls in LigneSortie.objects.select_related("article"):
        ex = list(ls.exemplaires.all())
        if ex:
            ls.etats = {"BON": len(ex)}
        elif ls.qte_livree:
            ls.etats = {"NEUF" if ls.article.type == "CONSOMMABLE" else "BON": ls.qte_livree}
        ls.save(update_fields=["etats"])
    for m in Magasin.objects.filter(type="MAGASIN"):
        for nom in ("Atelier – À réparer", "Rebut"):
            Emplacement.objects.get_or_create(magasin=m, nom=nom)


Migration.operations.append(migrations.RunPython(etats_existants, migrations.RunPython.noop))
